import argparse
import sys

def main():
    parser = argparse.ArgumentParser(description="Count whitespace-separated integers and print each value and count separated by one space in numeric order.")
    parser.add_argument("--min", type=int, help="Drop values below the supplied integer.")
    args = parser.parse_args()

    counts = {}
    for line in sys.stdin:
        for word in line.split():
            try:
                num = int(word)
                if args.min is not None and num < args.min:
                    continue
                counts[num] = counts.get(num, 0) + 1
            except ValueError:
                continue

    for num in sorted(counts.keys()):
        print(f"{num} {counts[num]}")

if __name__ == "__main__":
    main()

import json
import sys

def main():
    if len(sys.argv) < 2:
        print("Usage: python bookmark_manager.py <json_data_file>")
        sys.exit(1)

    json_data_file = sys.argv[1]
    bookmarks = load_bookmarks(json_data_file)

    while True:
        print("\nBookmark Manager")
        print("1. Add Name URL")
        print("2. List Bookmarks")
        print("3. Remove Name")
        print("4. Exit")
        choice = input("Enter your choice: ")

        if choice == "1":
            name = input("Enter name: ")
            url = input("Enter URL: ")
            bookmarks[name] = url
            save_bookmarks(json_data_file, bookmarks)
        elif choice == "2":
            print("\nBookmarks:")
            for name, url in sorted(bookmarks.items()):
                print(f"{name}\t{url}")
        elif choice == "3":
            name = input("Enter name to remove: ")
            if name in bookmarks:
                del bookmarks[name]
                save_bookmarks(json_data_file, bookmarks)
            else:
                print("Name not found.")
        elif choice == "4":
            sys.exit(0)
        else:
            print("Invalid choice. Please try again.")

def load_bookmarks(json_data_file):
    try:
        with open(json_data_file, 'r') as file:
            return json.load(file)
    except FileNotFoundError:
        return {}

def save_bookmarks(json_data_file, bookmarks):
    with open(json_data_file, 'w') as file:
        json.dump(bookmarks, file, indent=4)

if __name__ == "__main__":
    main()

import sys
import json
import decimal

def parse_csv(csv_data):
    return [tuple(map(decimal.Decimal, row)) for row in csv_data.splitlines()]

def summarize_expenses(expenses, category=None):
    if category:
        expenses = [expense for expense in expenses if expense[0] == category]
    total_expenses = sum(expense[1] for expense in expenses)
    return {
        "total": total_expenses.quantize(decimal.Decimal("0.01")),
        "categories": {category: expense[1].quantize(decimal.Decimal("0.01")) for category, expense in expenses}
    }

def main():
    if len(sys.argv) != 2:
        print("Usage: python expenses.py <csv_data>")
        sys.exit(1)

    csv_data = sys.stdin.read()
    expenses = parse_csv(csv_data)

    if len(expenses) == 0:
        print("No expenses found.")
        sys.exit(0)

    if len(expenses) == 1:
        category = expenses[0][0]
        summary = summarize_expenses(expenses, category)
        print(json.dumps(summary))
    else:
        summary = summarize_expenses(expenses)
        print(json.dumps(summary))

if __name__ == "__main__":
    main()

import sys

def print_board(board):
    print(" 1 | 2 | 3 ")
    print("-----------")
    print(" 4 | 5 | 6 ")
    print("-----------")
    print(" 7 | 8 | 9 ")

def check_winner(board):
    win_conditions = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8),  # rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8),  # columns
        (0, 4, 8), (2, 4, 6)               # diagonals
    ]
    for condition in win_conditions:
        if board[condition[0]] == board[condition[1]] == board[condition[2]] != ' ':
            return board[condition[0]]
    return None

def main():
    board = [' '] * 9
    current_player = 'X'
    print_board(board)

    while True:
        try:
            move = int(input(f"{current_player}'s turn (1-9): "))
            if move < 1 or move > 9 or board[move - 1] != ' ':
                raise ValueError("Invalid move")
            board[move - 1] = current_player
            print_board(board)
            winner = check_winner(board)
            if winner:
                print(f"{winner} wins!")
                break
            elif all(board[i] != ' ' for i in range(9)):
                print("Draw")
                break
            current_player = 'O' if current_player == 'X' else 'X'
        except ValueError as e:
            print(e)

if __name__ == "__main__":
    main()

import sys
import json

def validate_transactions(file_path):
    total_cents = 0
    with open(file_path, 'r') as file:
        for line_number, line in enumerate(file, start=1):
            if not line.strip():
                continue
            try:
                transaction = json.loads(line)
                if not isinstance(transaction, dict) or 'id' not in transaction or 'cents' not in transaction:
                    raise ValueError("Invalid transaction format")
                if not isinstance(transaction['id'], str) or not isinstance(transaction['cents'], int):
                    raise ValueError("Invalid transaction data")
                total_cents += transaction['cents']
            except json.JSONDecodeError:
                print(f"Error decoding line {line_number}: {line}", file=sys.stderr)
    return total_cents

def main():
    if len(sys.argv) != 2:
        print("Usage: python validate_transactions.py <file_path>", file=sys.stderr)
        sys.exit(1)
    file_path = sys.argv[1]
    total_cents = validate_transactions(file_path)
    print(total_cents)

if __name__ == "__main__":
    main()

import json
import sys

def load_quiz(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

def run_quiz(quiz):
    score = 0
    for question in quiz:
        print(question['question'])
        for answer in question['answers']:
            print(answer)
            user_answer = input().strip().lower()
            if user_answer == question['correct_answer'].lower():
                score += 1
    print(f"Score: {score}/{len(quiz)}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <quiz_file>")
        sys.exit(1)
    quiz_file = sys.argv[1]
    quiz = load_quiz(quiz_file)
    run_quiz(quiz)

if __name__ == "__main__":
    main()
